import java.util.*;
import java.io.*;

public class Main {

    static final InputStream IN = System.in;
    static final byte[] IBUF = new byte[1 << 16];
    static int ilen = 0, ipos = 0;

    static int readByte() throws IOException {
        if (ipos == ilen) {
            ilen = IN.read(IBUF, 0, IBUF.length);
            ipos = 0;
            if (ilen <= 0) return -1;
        }
        return IBUF[ipos++];
    }

    static int nextInt() throws IOException {
        int c = readByte();
        while (c != -1 && (c < '0' || c > '9')) c = readByte();
        int x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = readByte(); }
        return x;
    }

    static long[] heap = new long[1 << 16];
    static int hn = 0;

    static void hpush(long key) {
        if (hn == heap.length) heap = Arrays.copyOf(heap, heap.length << 1);
        int i = hn++;
        while (i > 0) {
            int par = (i - 1) >> 1;
            if (heap[par] <= key) break;
            heap[i] = heap[par];
            i = par;
        }
        heap[i] = key;
    }

    static long hpop() {
        long top = heap[0];
        long last = heap[--hn];
        if (hn > 0) {
            int i = 0;
            for (;;) {
                int l = 2 * i + 1;
                if (l >= hn) break;
                int c = (l + 1 < hn && heap[l + 1] < heap[l]) ? l + 1 : l;
                if (heap[c] >= last) break;
                heap[i] = heap[c];
                i = c;
            }
            heap[i] = last;
        }
        return top;
    }

    static int[] st;
    static long[] adj;

    static int posOf(int v, int t) {
        int lo = st[v], hi = st[v + 1];
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if ((int) (adj[mid] >>> 20) < t) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int N = nextInt(), M = nextInt(), K = nextInt();
        int[] P = new int[K + 1];
        for (int i = 1; i <= K; i++) P[i] = nextInt();
        int[] ev = new int[M], eu = new int[M], et = new int[M];
        for (int j = 0; j < M; j++) {
            ev[j] = nextInt();
            eu[j] = nextInt();
            et[j] = nextInt();
        }
        int A = nextInt(), B = nextInt();

        // CSR das arestas incidentes por estação; slot codificado como (t << 20) | (j*2 + lado)
        int[] deg = new int[N + 1];
        for (int j = 0; j < M; j++) { deg[ev[j]]++; deg[eu[j]]++; }
        st = new int[N + 2];
        for (int v = 1; v <= N; v++) st[v + 1] = st[v] + deg[v];
        adj = new long[2 * M];
        int[] fp = st.clone();
        for (int j = 0; j < M; j++) {
            adj[fp[ev[j]]++] = ((long) et[j] << 20) | (j << 1);
            adj[fp[eu[j]]++] = ((long) et[j] << 20) | ((j << 1) | 1);
        }
        for (int v = 1; v <= N; v++) Arrays.sort(adj, st[v], st[v + 1]);

        // nós: hub da estação v = id v-1 (0..N-1); nós (estação, sistema) = ids >= N
        int[] nodeId = new int[2 * M];
        int nextId = N;
        for (int v = 1; v <= N; v++) {
            for (int i = st[v], e2 = st[v + 1]; i < e2; i++) {
                if (i == st[v] || (adj[i] >>> 20) != (adj[i - 1] >>> 20)) nodeId[i] = nextId++;
                else nodeId[i] = nodeId[i - 1];
            }
        }
        int totalPairs = nextId - N;
        int totalNodes = N + totalPairs;

        // arestas dirigidas: mover dentro do sistema (custo 0); sair do sistema (0); entrar no sistema t (P[t])
        int cntE = 2 * M + 2 * totalPairs;
        int[] eFrom = new int[cntE], eTo = new int[cntE], eW = new int[cntE];
        int ei = 0;
        for (int j = 0; j < M; j++) {
            int nu = nodeId[posOf(ev[j], et[j])];
            int nv = nodeId[posOf(eu[j], et[j])];
            eFrom[ei] = nu; eTo[ei] = nv; eW[ei] = 0; ei++;
            eFrom[ei] = nv; eTo[ei] = nu; eW[ei] = 0; ei++;
        }
        for (int v = 1; v <= N; v++) {
            int hub = v - 1;
            for (int i = st[v], e2 = st[v + 1]; i < e2; i++) {
                if (i > st[v] && (adj[i] >>> 20) == (adj[i - 1] >>> 20)) continue;
                int t = (int) (adj[i] >>> 20);
                int node = nodeId[i];
                eFrom[ei] = node; eTo[ei] = hub; eW[ei] = 0; ei++;
                eFrom[ei] = hub; eTo[ei] = node; eW[ei] = P[t]; ei++;
            }
        }

        // CSR final do grafo de estados
        int[] cs = new int[totalNodes + 1];
        for (int i = 0; i < cntE; i++) cs[eFrom[i] + 1]++;
        for (int v = 0; v < totalNodes; v++) cs[v + 1] += cs[v];
        int[] gTo = new int[cntE], gW = new int[cntE];
        int[] gptr = new int[totalNodes];
        System.arraycopy(cs, 0, gptr, 0, totalNodes);
        for (int i = 0; i < cntE; i++) {
            int p = gptr[eFrom[i]]++;
            gTo[p] = eTo[i];
            gW[p] = eW[i];
        }
        eFrom = null; eTo = null; eW = null; fp = null; deg = null;

        // Dijkstra a partir do hub de A (entrar no primeiro sistema paga P[t])
        long[] dist = new long[totalNodes];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[A - 1] = 0;
        hn = 0;
        hpush(A - 1);
        while (hn > 0) {
            long key = hpop();
            int u = (int) (key & 0xFFFFF);
            long d = key >>> 20;
            if (d > dist[u]) continue;
            for (int p = cs[u], end = cs[u + 1]; p < end; p++) {
                int to = gTo[p];
                long nd = d + gW[p];
                if (nd < dist[to]) {
                    dist[to] = nd;
                    hpush((nd << 20) | to);
                }
            }
        }

        long ans = Long.MAX_VALUE;
        for (int i = st[B], e2 = st[B + 1]; i < e2; i++) ans = Math.min(ans, dist[nodeId[i]]);
        System.out.println(ans == Long.MAX_VALUE ? -1 : ans);
        System.out.flush();
    }
}
